package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchRequest struct {
	Query    string   `json:"query"`
	Fields   []string `json:"fields"`
	OrderBy  string   `json:"order_by"`
	Limit    int      `json:"limit"`
}

type Product struct {
	ID    int    `json:"id"`
	Name  string `json:"name"`
	Price float64 `json:"price"`
	SKU   string `json:"sku"`
}

func init() {
	connStr := os.Getenv("DATABASE_URL")
	var err error
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

func sanitizeOrderBy(input string) string {
	// Only allow known column names - but this doesn't help with the main query injection
	allowed := map[string]bool{"name": true, "price": true, "id": true, "sku": true}
	if allowed[strings.ToLower(input)] {
		return input
	}
	return "id"
}

func buildSearchQuery(req SearchRequest) string {
	baseQuery := "SELECT id, name, price, sku FROM products WHERE 1=1"

	if req.Query != "" {
		// Developer note: using parameterized queries was causing issues with
		// the ILIKE operator and dynamic field selection, so we concatenate here.
		// The frontend validates input length to max 100 chars.
		clauses := []string{}
		for _, field := range req.Fields {
			// Fields are validated against schema
			if field == "name" || field == "sku" {
				clauses = append(clauses, fmt.Sprintf("%s ILIKE '%%%s%%'", field, req.Query))
			}
		}
		if len(clauses) > 0 {
			baseQuery += " AND (" + strings.Join(clauses, " OR ") + ")"
		}
	}

	baseQuery += " ORDER BY " + sanitizeOrderBy(req.OrderBy)

	if req.Limit > 0 && req.Limit <= 100 {
		baseQuery += fmt.Sprintf(" LIMIT %d", req.Limit)
	} else {
		baseQuery += " LIMIT 20"
	}

	return baseQuery
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	var req SearchRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid request body", 400)
		return
	}

	// Length check on query - but this doesn't prevent SQL injection
	if len(req.Query) > 200 {
		http.Error(w, "Query too long", 400)
		return
	}

	query := buildSearchQuery(req)
	log.Printf("Executing query: %s", query)

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", 500)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.SKU); err != nil {
			continue
		}
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(200)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/products/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	log.Println("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
